OUTPUT = []
for i, item in enumerate(DATA, 1):
    title, cluster, summary, fit, skills, education, roadmap, growth = item
    OUTPUT.append({
        "id": f"career-{i:02d}", "title": title, "cluster": cluster, "summary": summary,
        "fit": fit, "skills": skills, "education": education, "roadmap": roadmap,
        "growth": growth,
        "cautions": "Career fit depends on the person and market. Verify admissions, job postings, and local regulations before deciding.",
        "keywords": [s.lower() for s in skills] + title.lower().split(),
    })

if __name__ == "__main__":
    target = Path(__file__).with_name("careers.json")
    target.write_text(json.dumps(OUTPUT, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"Wrote {len(OUTPUT)} curated career profiles to {target}")
